import{_ as t,o as e,c as l,a3 as o}from"./chunks/framework.BsQeBrPm.js";const p=JSON.parse('{"title":"DLC03・デルタの夜明け","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アエギプトゥス・灌漑システム・新祭神ソベクなどを解説（2026年11月追加予定）。","frontmatter":{"title":"DLC03・デルタの夜明け","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アエギプトゥス・灌漑システム・新祭神ソベクなどを解説（2026年11月追加予定）。"},"headers":[],"relativePath":"guide/dlc03-dawn-of-delta.md","filePath":"guide/dlc03-dawn-of-delta.md"}'),r={name:"guide/dlc03-dawn-of-delta.md"};function i(n,a,d,s,h,c){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="dlc03・デルタの夜明け" tabindex="-1">DLC03・デルタの夜明け <a class="header-anchor" href="#dlc03・デルタの夜明け" aria-label="Permalink to &quot;DLC03・デルタの夜明け&quot;">​</a></h1><blockquote><p>出典: <a href="https://www.anno-union.com/gamescom-recap-dawn-of-the-delta-and-echoes-of-kassandra/" target="_blank" rel="noreferrer">Anno Union公式ブログ「Gamescom recap: Dawn of the Delta and Echoes of Kassandra」</a>（2026年9月3日）。 2026年10月に詳細デブログ・ライブ配信が予定されており、本ページの内容は今後変更される可能性があります。</p></blockquote><blockquote><p>このページは作成中です。確定情報が増え次第、随時更新します。</p></blockquote><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>舞台は帝国南東部の<strong>アエギプトゥス</strong>（ナイル川デルタ地方）。</li><li>新規ゲーム開始時の地域として選択できるほか、既存セーブでもDLC有効化により探索可能になります。</li><li><strong>灌漑システム</strong>・新祭神・独自の軍事ユニットが導入されます。</li><li><strong>2026年11月</strong>、無料アップデート3.0と同時リリースが予定されています。</li></ul><h2 id="地形・建築エリア" tabindex="-1">地形・建築エリア <a class="header-anchor" href="#地形・建築エリア" aria-label="Permalink to &quot;地形・建築エリア&quot;">​</a></h2><p>土地は3つのゾーンに分かれます。</p><table tabindex="0"><thead><tr><th>ゾーン</th><th>特徴</th></tr></thead><tbody><tr><td>アリッドゾーン</td><td>現状は何も育たないが、建設用スペースが豊富</td></tr><tr><td>ファームランド</td><td>ナイル川に近い肥沃な土地。農業・林業向け</td></tr><tr><td>氾濫原</td><td>定期的に冠水し、生産に影響を与える</td></tr></tbody></table><h2 id="住民層" tabindex="-1">住民層 <a class="header-anchor" href="#住民層" aria-label="Permalink to &quot;住民層&quot;">​</a></h2><p>初期層は<strong>スレッシャー</strong>（農業の伝統を担う階層）です。進化先は次の2方向から選択できます。</p><ul><li><strong>スクライブ</strong>：ギリシャ・ローマ文化と融合した発展方向</li><li><strong>ポッター</strong>：エジプトの伝統を維持する発展方向</li></ul><p>各層で需要商品・必要な公共施設が異なります。</p><h2 id="灌漑システム" tabindex="-1">灌漑システム <a class="header-anchor" href="#灌漑システム" aria-label="Permalink to &quot;灌漑システム&quot;">​</a></h2><p>2つの方式が存在します。</p><ol><li><strong>ベイスン方式</strong>：盆地を造成し運河で接続することで、肥沃な土地を新たに作り出します。</li><li><strong>ノリア方式</strong>（ローマ化後に解放）：ノーリア水車から水路を通じて貯水槽（シスターン）周辺に給水します。</li></ol><h2 id="新しい商品・生産チェーン" tabindex="-1">新しい商品・生産チェーン <a class="header-anchor" href="#新しい商品・生産チェーン" aria-label="Permalink to &quot;新しい商品・生産チェーン&quot;">​</a></h2><ul><li>スタッフドグース（スクライブ向け需要品）</li><li>パピルス・筆記用具（スクライブ向け需要品）</li><li>その他の商品は未発表</li></ul><h2 id="宗教" tabindex="-1">宗教 <a class="header-anchor" href="#宗教" aria-label="Permalink to &quot;宗教&quot;">​</a></h2><p>新祭神が3柱導入される予定です。判明しているのは以下の1柱です。</p><ul><li><strong>ソベク</strong>：「デルタ川の神」。信仰すると灌漑システムと農場の管理が強化されます。</li></ul><h2 id="新軍事ユニット・船舶" tabindex="-1">新軍事ユニット・船舶 <a class="header-anchor" href="#新軍事ユニット・船舶" aria-label="Permalink to &quot;新軍事ユニット・船舶&quot;">​</a></h2><ul><li><strong>エリート・クシテ弓兵</strong>：高コストだが長射程・高精度。</li><li><strong>ドロメダリイ騎兵</strong>（ラクダ騎兵）：敵の騎兵・歩兵ユニットの士気を低下させる効果を持ちます。</li><li>川での移動速度が大幅に速いローカル船2種が追加されます（詳細未発表）。</li></ul><h2 id="その他" tabindex="-1">その他 <a class="header-anchor" href="#その他" aria-label="Permalink to &quot;その他&quot;">​</a></h2><ul><li>他地域との交易により、独自の経済戦略を構築できます。</li></ul><h2 id="未発表の要素" tabindex="-1">未発表の要素 <a class="header-anchor" href="#未発表の要素" aria-label="Permalink to &quot;未発表の要素&quot;">​</a></h2><p>以下は2026年10月のデブログ・ライブ配信での発表が予告されています。</p><ul><li>商品・生産チェーンの詳細</li><li>建物・スキルツリーの詳細</li><li>数値バランス（生産量・信仰要求量など）</li></ul>',27)])])}const b=t(r,[["render",i]]);export{p as __pageData,b as default};
